import {SURFACE_FIELDS,SURFACE_PRESETS,surfaceSettings} from './surface-settings.js?v=20261008-corners';
const $=s=>document.querySelector(s);
export function mountSurfaces(api){const group=document.createElement('details');group.className='ac-group surface-group';group.open=true;group.innerHTML=`<summary>03 / Surface grip</summary><p class="field-hint">Choose a starting setup, then adjust each surface independently.</p><div class="surface-presets">${Object.entries(SURFACE_PRESETS).map(([key,p])=>`<button type="button" data-surface-preset="${key}">${p.label}</button>`).join('')}</div><p id="surface-preset-description" class="field-hint"></p><div class="studio-fields">${Object.entries(SURFACE_FIELDS).map(([key,f])=>`<label class="studio-field">${f.label}<input id="ac-${key}" type="number" min="${f.min}" max="${f.max}" step="${f.step}"></label>`).join('')}</div><div class="surface-comparison" id="surface-comparison"></div><p class="field-hint">1.00 is the reference friction. More grip increases traction. Grass drag slows a car off the road; dirt pickup affects tire contamination. Kerbs remain flush and have no added vibration.</p><button id="reset-surface-grip" class="outline-button">Reset surface setup</button><p class="field-hint">These settings are included in the mod. Choose game weather separately in Content Manager.</p>`;
 $('.surface-slot').replaceWith(group);
 for(const [key,f] of Object.entries(SURFACE_FIELDS))$('#ac-'+key).onchange=()=>{const input=$('#ac-'+key),value=Number(input.value);if(input.value===''||!Number.isFinite(value)||value<f.min||value>f.max){api.toast(`Choose ${f.label.toLowerCase()} between ${f.min} and ${f.max}.`);refresh();return;}api.updateTrack(t=>t.export={...t.export,[key]:value});};
 group.querySelectorAll('[data-surface-preset]').forEach(button=>button.onclick=()=>{api.updateTrack(t=>t.export={...t.export,...SURFACE_PRESETS[button.dataset.surfacePreset].values});api.toast('Surface setup applied. Every value remains adjustable.');});
 $('#reset-surface-grip').onclick=()=>api.updateTrack(t=>t.export={...t.export,...surfaceSettings()});
 function refresh(){const settings=surfaceSettings(api.getTrack().export),preset=Object.entries(SURFACE_PRESETS).find(([,p])=>Object.entries(p.values).every(([key,value])=>Math.abs(settings[key]-value)<1e-7));for(const key of Object.keys(SURFACE_FIELDS))$('#ac-'+key).value=settings[key];group.querySelectorAll('[data-surface-preset]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.surfacePreset===preset?.[0])));$('#surface-preset-description').textContent=preset?.[1].description||'Custom setup. Use a preset to return to a balanced starting point.';$('#surface-comparison').innerHTML=['roadGrip','kerbGrip','pitGrip','grassGrip'].map(key=>`<div><span>${SURFACE_FIELDS[key].label}</span><i style="--grip:${settings[key]/1.2*100}%"></i><b>${settings[key].toFixed(2)}</b></div>`).join('');}
 return {refresh};
}
